import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    S = data[1].strip()

    if N <= 0:
        print(S)
        return

    if N >= len(S):
        print("0")
        return

    stack = []
    for digit in S:
        while N > 0 and stack and stack[-1] > digit:
            stack.pop()
            N -= 1
        stack.append(digit)

    # Remove remaining digits from the end if N > 0
    while N > 0 and stack:
        stack.pop()
        N -= 1

    # Remove leading zeros
    result = ''.join(stack).lstrip('0')

    if not result:
        print("0")
    else:
        print(result)

if __name__ == "__main__":
    main()
